#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<long long> T(N), F(M);
    for (int i = 0; i < N; i++) cin >> T[i];
    for (int i = 0; i < M; i++) cin >> F[i];

    sort(T.begin(), T.end(), greater<long long>());

    auto count_leq = [&](long long x) {
        long long cnt = 0;
        for (long long f : F) {
            cnt += x / f + 1;
        }
        return cnt;
    };

    long long lo = -1, hi = 1000000005LL;
    while (hi - lo > 1) {
        long long mid = lo + (hi - lo) / 2;
        if (count_leq(mid) >= N) hi = mid;
        else lo = mid;
    }

    vector<long long> coeff;
    coeff.reserve(N + M);

    for (long long f : F) {
        long long mx = hi / f;
        for (long long k = 0; k <= mx; k++) {
            coeff.push_back(k * f);
        }
    }

    sort(coeff.begin(), coeff.end());
    coeff.resize(N);

    long long ans = 0;
    for (int i = 0; i < N; i++) {
        ans += T[i] * coeff[i];
    }

    cout << ans << '\n';
    return 0;
}
